CREATE TABLE `activities` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '系統內部唯一編號',
  `external_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校方系統活動 ID，手動新增時為空',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '活動標題',
  `link` text COLLATE utf8mb4_unicode_ci COMMENT '活動官網原始詳細連結',
  `status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '報名狀態 (如：報名中、未開放、已截止)',
  `img_url` text COLLATE utf8mb4_unicode_ci COMMENT '校方伺服器原始圖片網址',
  `local_img_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '伺服器本地端圖片存放路徑',
  `views` int DEFAULT '0' COMMENT '累積瀏覽次數',
  `joined` int DEFAULT '0' COMMENT '目前報名人數',
  `target_audience` json DEFAULT NULL COMMENT '參與對象清單 (如：["學生", "教職員"])',
  `hour_labels` json DEFAULT NULL COMMENT '時數類別標籤清單',
  `sdg_labels` json DEFAULT NULL COMMENT 'SDGs 永續目標標籤清單',
  `content_hash` char(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '核心內容 MD5 雜湊值，用於精準偵測標題或狀態變動',
  `source` enum('crawler','manual') COLLATE utf8mb4_unicode_ci DEFAULT 'crawler' COMMENT '資料來源：crawler (爬蟲自動抓取), manual (人員手動新增)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '資料建立日期',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最後異動日期 (包含人數與瀏覽數更新)',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '軟刪除標記，不為空代表資料已刪除但保留於底層',
  PRIMARY KEY (`id`),
  UNIQUE KEY `external_id` (`external_id`),
  KEY `idx_external_id` (`external_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
