/*!40000 ALTER TABLE `departments` DISABLE KEYS */;
INSERT INTO `departments` VALUES (1,'{\"en-US\": \"Office of Student Affairs\", \"zh-TW\": \"學務處\"}','{\"en-US\": \"The Office of Student Affairs is devoted to the service of student affairs and the establishment of comfortable and excellent environment for living and learning on campus. Through our administration, services and sponsorships, students at NCU can enjoy their college life in addition to rigorous academic learning. The NCU campus is enriched by a variety of extracurricular activities, student clubs and social events. All of these not only enable our students to uncover their potential, creativity and imagination, but also advocate them to be confident, disciplined, independent and cooperative.\\n\\n　　We believe these characteristics strengthen our students\' competitiveness in their future career developments. As a strong tradition of NCU, underscoring of humanism and social responsibility for students in all activities is practiced by the Office of Student Affairs. The core values of our missions are Interdisciplinary, Intellectual, Inspiration (3I) and Communication, Cooperation, Confidence (3C) .\", \"zh-TW\": \"學務處致力於建構優質的生活學習環境與文化，激發學生的潛能、創造力、想像力、與競爭力，倡導自愛、自律、自主、自由，強調人本與自然、人性關懷與社會責任。以3C-Communication (溝通)、Cooperation (合作)、Confidence (信心)及3I-Interdiscipline (跨領域)、Intellect (知識、智慧)、Inspiration (啟發、鼓舞) 為核心，透過課外學習之機制，提昇學生的軟實力，型塑中大學生的特色，建立中大人之向心力與認同感。\"}','ncu7200@ncu.edu.tw','{\"en-US\": \"\", \"zh-TW\": \"\"}',NULL,0,1,'2026-01-25 08:31:56','2026-01-25 09:18:09',NULL),(2,'{\"en-US\": \"Student Services Division\", \"zh-TW\": \"生活輔導組\"}','{\"en-US\": \"Student Services Division, offering proper source to help those who face problems or any difficulties and handling all safety matters and emergent events on campus. Students can get a better environment for living and learning on campus.\\n\\n- Student Loans\\n\\n- Scholarships\\n\\n- Student Award and Discipline\\n\\n- Emergency Relief\\n\\n- National Military Service\\n\\n- Tuition Reduction and Exemption\\n\\n- Deduction of Military Service Period\\n\\n- Traffic Safety\\n\\n- Military Education Curriculum\\n\\n- Safety Issues for Students at Department or Institute\\n\\n- Students Off-Campus Rental Affairs\\n\\n- Chun Hui Project\", \"zh-TW\": \"本組提供適當助學資源，協助學生解決日常生活中所遭遇之問題與困難，進而關懷學生使其得以專心向學、陶冶品德並維護學生及校園安全。\"}','ncu7221@ncu.edu.tw','{\"en-US\": \"http://studentservices.ncu.edu.tw/wp/\", \"zh-TW\": \"https://military.ncu.edu.tw/epaper/index.php\"}','office01.gif',1,1,'2026-01-25 08:31:56','2026-01-25 08:31:56',NULL),(3,'{\"en-US\": \"Counseling Center\", \"zh-TW\": \"諮商輔導中心\"}','{\"en-US\": \"- Individual Counseling\\n\\n- Group Counseling\\n\\n- Psychological Tests\\n\\n- Mental health speech and Forum\\n\\n- Freshman Orientaion\\n\\n- Advisor/advisee marshaling\\n\\n- Special Education Resource Room - Services and supports for students with disability\\n\\n　　By providing counseling services and campus activities for mental health, the Counseling Center helps students to grow, improve interpersonal relation and enjoy different perspectives of college life.\", \"zh-TW\": \"藉由提供心理諮商服務及心理衛生推廣活動，增進學生自我瞭解與成長。\"}','ncu7263@ncu.edu.tw','{\"en-US\": \"http://love.adm.ncu.edu.tw/NCU_counsel/Eng-index.php\", \"zh-TW\": \"https://love.adm.ncu.edu.tw/NCU_counsel/\"}','office02.gif',2,1,'2026-01-25 08:31:56','2026-01-25 08:31:56',NULL),(4,'{\"en-US\": \"Extracurricular Activity Section\", \"zh-TW\": \"課外活動組\"}','{\"en-US\": \"- Student Organizations and Student Association\\n\\n- Orientation\\n\\n- Commencement Ceremony\\n\\n- Club Evaluation\\n\\n- Student Leader Training Programs\\n\\n- Student Activity Venue Management\\n\\n　　Extracurricular Activities Division provides administrative guidance and financial supports to over 100 student clubs in NCU for organizing various school events, intramural and extramural competitions or activities.\", \"zh-TW\": \"本校正式成立約110餘個學生社團，依性質分為系學會、學術性、康樂性、服務性、體育性及聯誼性等類別，本組輔導社團辦理活動及經費申請之外，並定期辦理社團評鑑、社團負責人研習、社團博覽會等，促進社團發展，培養團隊合作精神\\n\\n    本組提供課外組所屬場地及器材借用，輔導藝工隊/小中大電視台支援藝文活動，建構優質課外學習環境。此外，籌辦校內外大型活動：畢業典禮、新生營、四中五校聯誼賽等，活絡校園風氣，打造青年學子的黃金歲月。\"}','ncu7231@cc.ncu.edu.tw','{\"en-US\": \"http://club.adm.ncu.edu.tw/api/set_lang/en\", \"zh-TW\": \"https://club.adm.ncu.edu.tw/\"}','office03.gif',3,1,'2026-01-25 08:31:56','2026-01-25 08:31:56',NULL),(5,'{\"en-US\": \"Career Center\", \"zh-TW\": \"職涯發展中心\"}','{\"en-US\": \"- Career Evaluation and Guidance\\n\\n- Career Consultation Services\\n\\n- Career Campus Talent Recruitment\\n\\n- On-campus\\n\\n- Corporate Visits\\n\\n- NCU off-campus Internship Program\\n\\n- Graduate Questionnaires Collection and Statistics\\n\\n　　The Career Center navigates NCU students to develop their potential, explore future possibilities and offers comprehensive resources for them to make informed career decisions. The division provides high quality services, programs and events to help students reach their goals.\", \"zh-TW\": \"提升中大學生職場就業率及競爭力，引領與豐厚生涯發展之實力，培育與激發多元才能，追蹤與輔導職涯流向。\"}','ncu7241@ncu.edu.tw','{\"en-US\": \"http://careercenter.ncu.edu.tw/\", \"zh-TW\": \"http://careercenter.ncu.edu.tw/\"}','office04.gif',7,1,'2026-01-25 08:31:56','2026-01-25 08:31:56',NULL),(6,'{\"en-US\": \"Center for Service Learning\", \"zh-TW\": \"服務學習發展中心\"}','{\"en-US\": \"- Service-Learning Courses and Service\\r\\n- Learning Mentor\\n\\n- International Service Learning\\n\\n- NCU Learning Passport\\n\\n- Volunteer Training Programs and Community Services\\n\\n　　Service-Learning Division is responsible for service-learning courses and various volunteer programs which combine community service with learning and reflection to enrich students\' learning experience and enhance civic responsibility.\", \"zh-TW\": \"透過服務學習課程與志工服務計畫，將社區服務與學習反思結合，藉以豐富學生的學習經驗，培養公民責任。\"}','ncu57235@ncu.edu.tw','{\"en-US\": \"http://passport.ncu.edu.tw/\", \"zh-TW\": \"https://service-learning.ncu.edu.tw/\"}','office05.gif',4,1,'2026-01-25 08:31:56','2026-01-25 08:31:56',NULL),(7,'{\"en-US\": \"Health Center\", \"zh-TW\": \"衛生保健組\"}','{\"en-US\": \"- Injury Treatment\\n\\n- Medical Support\\n\\n- Health Examination\\n\\n- Nutrition Consultation\\n\\n- Campus Food Hygiene Management\\n\\n- Student Group Insurance\\n\\n- Smoking Quitting, Control and Prevention\\n\\n- Accidental Injury Prevention Education Program\\n\\n- CPR & AED Training\\n\\n- Infectious Disease Prevention\\n\\n　　The core mission of Health Center is to provide fundamental health care and emergency assistance upon the idea of \\\"attentiveness, caring and innovation.\\\"\", \"zh-TW\": \"以「用心、愛心、創新」為健康照護服務的核心價值，創造健康快樂的學習情境。結合社區資源，辦理多元化健康促進活動。\"}','ncu7270@ncu.edu.tw','{\"en-US\": \"http://140.115.183.208/en\", \"zh-TW\": \"https://health.ncu.edu.tw/\"}','office06.gif',6,1,'2026-01-25 08:31:56','2026-01-25 08:31:56',NULL),(9,'{\"en-US\": \"Indigenous students resource center\", \"zh-TW\": \"原住民族學生資源中心\"}','{\"en-US\": \"1. Execute all business duties for the Aboriginal Student Resource Center.\\n\\n2. Establish an exchange platform for the integration of the aboriginal affairs of the school with resources for aboriginal students.\\n\\n3. Provide life and academic counseling for aboriginal students.\\n\\n4. Handle national education courses and activities for aboriginal students.\\n\\n5. Manage all aboriginal student related affairs.\\n\\n6. Take care of any temporary tasks.\", \"zh-TW\": \"原住民資源中心以協助本校原住民族學生各式輔導課程及資源為主，同時普查與強化建置原住民生基本資料庫，讓學生資料更加完整，並於每年辦理部落文化體認，提升族群意識及促進文化交流，進而保留和推廣台灣原住民文化。\"}','chiangmiss@ncu.edu.tw','{\"en-US\": \"http://ncuisrc.ncu.edu.tw/index.php?fbclid=IwAR0dueckCT4t4ndJknXxozLQkCAHrY8G2nFGbwfHY7Xo2h4joVnvuHGaqqk\", \"zh-TW\": \"http://ncuisrc.ncu.edu.tw/index.php?fbclid=IwAR0dueckCT4t4ndJknXxozLQkCAHrY8G2nFGbwfHY7Xo2h4joVnvuHGaqqk\"}',NULL,8,1,'2026-01-25 08:31:56','2026-01-25 09:18:09',NULL),(10,'{\"en-US\": \"Student Housing Service Division\", \"zh-TW\": \"住宿服務組\"}','{\"en-US\": \"We dedicate to \\\"Caring all the student sincerely\\\", \\\"Arrange after-school activities for residents\\\", \\\"Create a friendly environment \\\", and \\\"Deal with everything patiently\\\" to build a \\\"Healthy, Learning, Safe, and Comfortable\\\" NCU Dormitory.\", \"zh-TW\": \"住宿服務組主要辦理業務為宿舍床位申請（含寒暑假住宿）、宿舍押金退費、宿舍抽籤規劃、床位調整、開關舍規劃、宿舍修繕服務、宿舍各式活動辦理、宿舍幹部遴選等等，同學若有任何宿舍事務問題，皆可到住宿服務組，我們將盡力為您解答。 \\n\\n§ 位置：國際學舍一樓，地球科學院對面 \\n\\n§ 服務時間：(一) ~ (五) 08:30~17:00\"}','ncu57290@cc.ncu.edu.tw','{\"en-US\": \"\", \"zh-TW\": \"https://in.ncu.edu.tw/~ncu7221/OSDS/index.php\"}',NULL,5,1,'2026-01-25 08:31:56','2026-01-25 09:18:09',NULL);
/*!40000 ALTER TABLE `departments` ENABLE KEYS */;
UNLOCK TABLES;

