INSERT INTO `osa2014_event` VALUES (3213,'教育部製作「四防齊心、校園安心」校園安全文宣資料(影片及圖卡)，建請師生抽空點閱及運用~',NULL,1,'2025-10-28 00:00:00','2026-06-30 00:00:00',NULL,NULL,NULL,'<p><strong>各位師長、同學們好：</strong></p>\r\n\r\n<p><strong>教育部製作「四防齊心、校園安心」校安文宣資料(影片及圖卡)，請大家抽空點閱，增加自我校園安全防範知能。</strong></p>\r\n\r\n<p><strong>█內容包含：</strong></p>\r\n\r\n<p><strong>一、動畫6部：</strong></p>\r\n\r\n<p><strong>1.防制藥物濫用1部-【藥命的誘惑】</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆精華版：<a href=\"https://youtu.be/DuqGXL_hm_Y\">https://youtu.be/DuqGXL_hm_Y</a></strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆完整版：<a href=\"https://youtu.be/1I_6VCSLK54\">https://youtu.be/1I_6VCSLK54</a></strong></p>\r\n\r\n<p><strong>&nbsp;2.學生詐騙防制1部-【SSR的誘惑】</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆精華版：<a href=\"https://youtu.be/E36UPzaJNNI\">https://youtu.be/E36UPzaJNNI</a>&nbsp;</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆完整版：<a href=\"https://youtu.be/yeFqVbTWPV0\">https://youtu.be/yeFqVbTWPV0</a></strong></p>\r\n\r\n<p><strong>&nbsp;3.學生交通安全1部-【轉角】</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆精華版：<a href=\"https://youtu.be/Q2t0Utwml7I\">https://youtu.be/Q2t0Utwml7I</a></strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆完整版：<a href=\"https://youtu.be/-eB1XFn1JAg\">https://youtu.be/-eB1XFn1JAg</a></strong></p>\r\n\r\n<p><strong>&nbsp;4.防制校園霸凌2部-</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp;(1)防制校園霸凌-1【濾鏡之外】</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆精華版：<a href=\"https://youtu.be/moRgWZqVUvk\">https://youtu.be/moRgWZqVUvk</a></strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆完整版：<a href=\"https://youtu.be/hQhLE5hahqg\">https://youtu.be/hQhLE5hahqg</a></strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp;(2)防制校園霸凌-2【舞力挺】</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆精華版：<a href=\"https://youtu.be/KEKpbtAELeM\">https://youtu.be/KEKpbtAELeM</a></strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆完整版：<a href=\"https://youtu.be/ocEkfgV_R48\">https://youtu.be/ocEkfgV_R48</a></strong></p>\r\n\r\n<p><strong>&nbsp;5.學生賃居安全1部-【不存在的房間】</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆精華版：<a href=\"https://youtu.be/GbFXAuL3hgM\">https://youtu.be/GbFXAuL3hgM</a></strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; ◆完整版：<a href=\"https://youtu.be/OZ-5A_pXucw\">https://youtu.be/OZ-5A_pXucw</a></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>二、圖卡32張(連結：&nbsp;<a href=\"https://reurl.cc/EQMzQg\">https://reurl.cc/EQMzQg</a>&nbsp;)</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; 1.學生詐騙防制9張</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; 2.學生交通安全9張</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; 3.防制校園霸凌9張</strong></p>\r\n\r\n<p><strong>&nbsp; &nbsp; 4.學生賃居安全5張</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>三、亦請師長、學生幹部協助利用各院週會、電子看版、Line群組及各項學生集會時機，加強宣教，以收實效。</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>學務處生輔組校安中心&nbsp; 敬上&nbsp; &nbsp;114.10.27</strong></p>\r\n',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,29,'2025-10-28 11:05:45',3,1,3),(3225,'公告辦理114學年度第2學期住宿生申請不續住宿舍作業','To announce the application for not extending the stay at the dormitory in the 2nd semester of 2025.',1,'2025-12-12 00:00:00','2026-02-28 00:00:00',NULL,NULL,NULL,'<p><strong>公&nbsp; &nbsp;&nbsp;&nbsp;告 &nbsp;&nbsp;&nbsp;</strong><strong>&nbsp;&nbsp;</strong><strong>&nbsp;</strong>114中大學宿字第022號</p>\r\n\r\n<p>主旨：公告辦理114學年度第2學期住宿生申請不續住宿舍作業。</p>\r\n\r\n<p>依據：本校學生宿舍管理辦法第5條第3款、第6條第8款、第9條第2款與第22條第2款。</p>\r\n\r\n<p>公告事項：</p>\r\n\r\n<ul>\r\n	<li>適用對象：114學年度第1學期住宿生。</li>\r\n	<li>申請時間與流程(操作手冊請參閱附件)</li>\r\n</ul>\r\n\r\n<p>(一)放棄下學期宿舍床位：即日起至115年1月31日止。</p>\r\n\r\n<ol>\r\n	<li>\r\n	<ol>\r\n		<li>請至Portal登入-&gt;服務櫃台(iNCU)-&gt;學務專區-&gt;宿舍申請/查詢內-&gt;其他項目-&gt;<strong>放棄下學期宿舍</strong>。</li>\r\n		<li>確認放棄後系統會寄發Email至服務櫃台(iNCU)所設定的個人信箱。</li>\r\n	</ol>\r\n	</li>\r\n</ol>\r\n\r\n<p>(二)逾期放棄下學期宿舍床位：115年2月1日~115年2月22日止</p>\r\n\r\n<ol>\r\n	<li>請至Portal登入-&gt;服務櫃台(iNCU)-&gt;學務專區-&gt;宿舍申請/查詢內-&gt;其他項目-&gt;<strong>個人歷年資料申請</strong>-&gt;逾期放棄申請。</li>\r\n	<li>確認放棄後會於系統<strong>個人歷年資料申請</strong>顯示狀態為<strong>逾期放棄</strong>。</li>\r\n	<li><strong>依據宿舍管理辦法第</strong><strong>6</strong><strong>條第</strong><strong>8</strong><strong>款逾期辦理放棄者，次一學年宿舍抽籤順序列第三順位；第</strong><strong>22</strong><strong>條第</strong><strong>2</strong><strong>款第</strong><strong>1</strong><strong>項逾放棄住宿基準日而於當學期開學日前放棄住宿者，需繳交學期住宿費七分之一。</strong></li>\r\n</ol>\r\n\r\n<p>(三)上述作業僅放棄下學期宿舍，還須另行辦理退宿手續。</p>\r\n\r\n<ul>\r\n	<li>注意事項\r\n	<ol>\r\n		<li><strong>凡申請放棄住宿者，務請於</strong><strong>115</strong><strong>年</strong><strong>1</strong><strong>月</strong><strong>31</strong><strong>日下午</strong><strong>1</strong><strong>點前遷出宿舍並完成退宿手續</strong>，未於退宿期限內搬遷者，依宿舍管理辦法第9條第2款處理其留置物品。</li>\r\n		<li>若於114學年第1學期畢業者，畢業離校前須完成退宿手續，最遲不得超過115年1月31日(五)13點前辦理。於115年1月31日(六)13點前內遷出宿舍並完成退宿手續。</li>\r\n		<li>退宿程序\r\n		<ol>\r\n			<li>請至退宿檢查系統：請至Portal登入-&gt;服務櫃台(iNCU)-&gt;學務專區-&gt;宿舍申請/查詢內-&gt;個人歷年申請資料查詢-&gt;退宿申請。</li>\r\n			<li>將寢室清潔完成照片上傳到退宿檢查系統(照片上傳以2MB以下較佳)，請至所屬宿舍傳達室找宿舍管理員到寢室檢查確認，並將鑰匙繳交至宿舍傳達室給宿舍管理員。退宿檢查不合格者，需繳交清潔不合格費用或鑰匙遺失費用。</li>\r\n			<li>若未完成退宿手續者，視同逾期未退宿，需繳交清潔不合格費用或鑰匙遺失費用。</li>\r\n			<li>未於退宿期限內搬遷者，依宿舍管理辦法第9條第2款處理其留置物品。</li>\r\n		</ol>\r\n		</li>\r\n		<li><strong>開學後自願退宿剩餘未住宿月份住宿費需先扣除本款第一項七分之一學期住宿費後退還。若扣除學期住宿費七分之一後，所餘住宿費餘額為負數者則不予退款，不足額費用須另繳交。</strong></li>\r\n		<li><strong>女</strong><strong>14</strong><strong>舍預定於</strong><strong>115</strong><strong>年度</strong><strong>7-9</strong><strong>月起進行為期一年宿舍整修，屆時需請住宿生搬遷至其他宿舍，待相關工程確定後將另行公告。</strong></li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 學生事務處住宿服務組</p>\r\n','<p><strong>&nbsp;Announcement</strong></p>\r\n\r\n<p>114National Central University dorm No.022</p>\r\n\r\n<p>Subject: To announce the application for not extending the stay at the dormitory in the 2nd semester of 2025.</p>\r\n\r\n<p>Basis: According to Article 5-3, 6-8, 9-2 and 22-2 of Regulations for Student Dormitories</p>\r\n\r\n<p>Contents:</p>\r\n\r\n<ol>\r\n	<li>Applicability: All students of NCU at the dormitory in the 1st semester of 2025.</li>\r\n	<li>Procedure and time (Instructions are listed in the attached file):\r\n	<ol>\r\n		<li>The range of time to Give up the dormitory: From now until January 31, 2026.\r\n		<ol>\r\n			<li>Login to NCU Portal-&gt;iNCU-&gt;Student Affair (StdAffair) -&gt;Dorm Application and Search -&gt; Other Items -&gt; <strong>Give up the next Semester Dorm</strong></li>\r\n			<li>The system will notify you via the email you set in iNCU after you successfully abandoned.</li>\r\n		</ol>\r\n		</li>\r\n		<li>Abandoning the dormitory after the expiration date: From February 1, 2026 to February 22, 2026.\r\n		<ol>\r\n			<li>Login to NCU Portal-&gt;iNCU-&gt;Student Affair (StdAffair) -&gt;Dorm Application and Search -&gt; Other Items -&gt;<strong>Personal information inquiry over the years </strong>-&gt; Abandoning dormitory overdue</li>\r\n			<li>After confirming the abandonment, it will be displayed in the system as &ldquo;overdue abandon&rdquo;</li>\r\n			<li><strong>According to Regulations for Student Dormitories. Article 6-8, for those who waive beyond the deadline, the sequence of lot-drawing will be arranged to the third priority in next academic year. Article 22-2, if you give up your accommodation before the start of the semester after the base date for giving up your accommodation, you will be required to pay one seventh of the accommodation fee for the semester.</strong></li>\r\n		</ol>\r\n		</li>\r\n		<li>The above assignment only gives up the dormitory for the next semester, and separate check-out procedures are required.</li>\r\n	</ol>\r\n	</li>\r\n	<li>Instructions:\r\n	<ol>\r\n		<li>For those who apply to waive accommodation, please move out of the dormitory within the specified time and complete the check-out procedure before 2026 January 31 1:00 P.M..</li>\r\n		<li>students graduating in the 2nd semester of the 2025 academic year are required to complete the check-out procedure before or at the latest by January 31 1:00 P.M., 2026.</li>\r\n		<li>Check-out procedures (detailed instructions for the check-out process will be announced separately)\r\n		<ol>\r\n			<li>To check-out system: Login to NCU Portal -&gt;iNCU-&gt; Student Affair (StdAffair) -&gt;Dorm Application and Search -&gt;Personal information inquiry over the years-&gt;Check-out application.</li>\r\n			<li>Take photos of your dormitory&#39;s cleanliness, upload to check-out system (photo size &lt;2MB is preferable) and return the key to the key box at the dormitory office. The dormitory manager/dormitory officer will visit your room to verify that the cleanliness meets the standard.</li>\r\n			<li>There will be a fee for those who didn&rsquo;t meet the cleanliness standard or lost in room keys.</li>\r\n			<li>If the check-out procedure is not completed, it will be treated as overdue check-out, and you will be required to pay a fee for non-compliance with cleanliness standards or for lost keys.</li>\r\n			<li>Those who do not move out within the check-out deadline will have their belongings handled in accordance with Article 9, Section 2 of the dormitory regulations.</li>\r\n		</ol>\r\n		</li>\r\n		<li><strong>Regarding voluntary withdrawal from the dormitory after the beginning of school, the fee of the remaining months will only be refunded after the deduction of 1/7 of the dormitory fee of that semester as listed in Paragraph 1 of this section. If the dormitory fee of the remaining months is not enough to cover 1/7 of the dormitory fee of that semester, boarders will be asked to pay for the relevant cost.</strong></li>\r\n		<li><strong>Dormitory No. 14 (Female) is scheduled to undergo renovation from July to September of 2026 for a period of one year. During this time, residents will be required to relocate to other dormitories. Further announcements will be made once the project details are finalized.</strong></li>\r\n	</ol>\r\n	</li>\r\n</ol>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Student Services and Dormitory Division, Office of Student Affairs</p>\r\n',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,33,'2025-12-12 14:11:38',3,0,3),(3226,'公告辦理114學年度第2學期未住宿學生申請宿舍作業','To announce the application for the waiting list for student dormitories in the 2nd semester of 2025.',1,'2025-12-12 00:00:00','2026-02-28 00:00:00',NULL,NULL,NULL,'<p><strong>公&nbsp; &nbsp;&nbsp;告 &nbsp;</strong><strong>&nbsp;&nbsp;</strong><strong>&nbsp;&nbsp;&nbsp;&nbsp;</strong>114中大學宿字第023號</p>\r\n\r\n<p>主旨：公告辦理114學年度第2學期未住宿學生申請宿舍作業。</p>\r\n\r\n<p>依據：學生宿舍管理辦法第6條辦理。</p>\r\n\r\n<p>公告事項：</p>\r\n\r\n<ul>\r\n	<li>適用對象：114學年度第1學期未住宿學生且114學年度第2學期仍在學者。</li>\r\n	<li>申請時間：即日起至115年2月24日(例假日除外)，每日09:00~17:00，中午12:00-13:00除外。</li>\r\n	<li>申請文件與方式：\r\n	<ol>\r\n		<li>請詳閱本校學生宿舍管理辦法<a href=\"https://reurl.cc/aMdda3\">https://reurl.cc/aMdda3</a>，無法遵守者請勿申請。</li>\r\n		<li>填寫「住宿申請表」(請至住宿服務組網頁下載<a href=\"https://reurl.cc/1kbbem\">https://reurl.cc/1kbbem</a>或至住宿服務組索取)，將填妥之「住宿申請表」送至住宿服務組。亦可於截止日前，以傳真(03-4263925)或電子郵件(<a href=\"mailto:ncu57290@cc.ncu.edu.tw\">ncu57290@cc.ncu.edu.tw</a>)傳遞。</li>\r\n		<li>本學期休學生，如欲申請宿舍需完成復學後請於申請宿舍時一併提供復學證明書。</li>\r\n		<li>住宿服務組安排床位後，將核定床位的住宿申請表以Email回傳給申請者，如須放棄申請床位者，請於床位通知後10天內辦理放棄床位，逾期放棄需繳交1/7住宿費用。</li>\r\n	</ol>\r\n	</li>\r\n	<li>說明\r\n	<ol>\r\n		<li>114學年度第2學期可入住時間為115年2月1日上午10時，其住宿費用納入學雜費一併繳交。</li>\r\n		<li>如需提前於114-2學期可入住時間辦理入住手續者，依入住時間繳交部分住宿費。</li>\r\n		<li>入住手續：請持核定的住宿申請表至所屬宿舍傳達室，並出示已核定床位之QRcode，路徑：請至Portal登入-&gt;服務櫃台(iNCU)-&gt;學務專區-&gt;宿舍申請/查詢內-&gt;個人歷年申請資料查詢-&gt;114第2學期-&gt;檢視詳細資料-&gt;顯示QRcode</li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p>入住時請確認請取鑰匙為金色鑰匙及確認寢室清潔(可參考宿舍清潔標準<a href=\"https://reurl.cc/86Ga3o\">https://reurl.cc/86Ga3o</a>)與設備，若有任何問題請立即向宿舍管理員反映。</p>\r\n\r\n<ul>\r\n	<li>\r\n	<ol>\r\n		<li>依宿舍管理辦法規定，宿舍床位非經允許不得轉讓或調整，若辦理入住時有床位占用情形，請勿私下同意交換床位，請告知宿舍管理員協助辦理。</li>\r\n		<li>如有想入住的宿舍寢室，請自行至「學務專區-&gt;宿舍申請/查詢-&gt;學期空床位資料查詢」查詢。</li>\r\n	</ol>\r\n	</li>\r\n	<li>備註\r\n	<ol>\r\n		<li>各宿舍收費標準請參閱國立中央大學學生宿舍收費一覽表(114學年適用)。</li>\r\n		<li>因應教育部補助大專院校學生住宿費一般生每學期5000元，低收/中低收入戶生每學期7000元，請申請時一併告知身分。</li>\r\n		<li>女14舍、男13舍、國際學舍、曦望居、中大會館宿舍寢室電費須自付。</li>\r\n		<li>中大會館床位數少將依申請順序做安排，若申請時已無中大會館床位，將安排至其他棟宿舍。</li>\r\n		<li>曦望居為性別友善宿舍，男女分棟混住，採公共區域共用與同出入口進出；中大會館為性別友善宿舍，不另外區分男女生樓層，公共區域共用與同出入口進出。</li>\r\n		<li>依據112年3月13日電算中心推動中大會館之宿舍網路全面收費討論會議決議，因應中大會館宿舍網路目前狀況和需求，電算中心有營運成本考量故不提供中大會館宿網，有宿網需求的同學建議使用電算中心提供之方案(中華電信固網)。</li>\r\n		<li><strong>女</strong><strong>14</strong><strong>舍預定於</strong><strong>115</strong><strong>年度7</strong><strong>-9</strong><strong>月起進行為期一年宿舍整修，屆時需請住宿生搬遷至其他宿舍，待相關工程確定後將另行公告。</strong></li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;學務處住宿服務組</p>\r\n<?php echo 123456;','<p>Announcement &nbsp;&nbsp;&nbsp;&nbsp;114 National Central University Dorm No. 023</p>\r\n\r\n<p>Subject: To announce the application for the waiting list for student dormitories in the 2nd semester of 2025.</p>\r\n\r\n<p>Basis: According to Article 6 of Regulations for Student Dormitories.</p>\r\n\r\n<p>Notice:</p>\r\n\r\n<ol>\r\n	<li>Applicants: Students in 1st semester of 2025 academic year without accommodation and students still studying in 2025 academic year.</li>\r\n	<li>Application time: From now until Feb. 24, 2026. Working hours: 09:00 ~ 17:00 daily, except the lunch break starts from 12:00 to 13:00.</li>\r\n	<li>Application documents and methods:</li>\r\n</ol>\r\n\r\n<ol>\r\n	<li>Please read the school&rsquo;s Student Dormitory Management Practices. Applicants who cannot comply with the practices please do not apply. The download website of Student Dormitory Management Practices: <a href=\"https://reurl.cc/aMdda3\">https://reurl.cc/aMdda3</a>.</li>\r\n	<li>Complete the &ldquo;Accommodation Application Form&rdquo; (you may download the regulatory form from the website of Dormitory Service Center: <a href=\"https://reurl.cc/1kbbem\">https://reurl.cc/1kbbem</a> or pick up the Form at Office of Student Dormitory Service). Submit the completed &ldquo;Accommodation Application Form&rdquo; to the Dormitory Service Center. You may also submit the application form via fax (03-4263925) or email (<a href=\"mailto:ncu57290@cc.ncu.edu.tw\">ncu57290@cc.ncu.edu.tw</a>) before the deadline.</li>\r\n	<li>Students on leave for the current semester who wish to apply for dormitory accommodation must provide a reinstatement certificate upon applying for the dormitory after resuming their studies.</li>\r\n	<li>Upon arranging the beds, the Dormitory Service Center will email back the Accommodation Application Form of Bed Authorization to the applicants. If you need to give up your application for a bed, please give up the bed within 10 days after the bed is notified. If you give up after the deadline, you will be charged one-seventh of the accommodation fee.</li>\r\n</ol>\r\n\r\n<ol>\r\n	<li>Illustration</li>\r\n</ol>\r\n\r\n<ol>\r\n	<li>For the second semester of the 2025 academic year, check-in will begin at 10:00 a.m. on February 1, 2026 and the dormitory fee will be paid along with the tuition and miscellaneous fees.</li>\r\n	<li>If you need to check in in advance before the available check-in time in the second semester of the 2025 academic year, you must pay part of the accommodation fee according to the check-in time.</li>\r\n	<li>Check-in procedure: Please bring the accommodation application form to the dormitory communication office for processing. When checking in and residents must present the approved bed assignment QR code upon check-in. Login to NCU Portal-&gt;iNCU-&gt;Student Affair (StdAffair) -&gt;Dorm Application and Search -&gt; Other Items -&gt;Personal information inquiry over the years -&gt; View detailed information -&gt; Display QR code</li>\r\n</ol>\r\n\r\n<p>please confirm that the key is a golden key and confirm that the dormitory is clean (refer to the dormitory cleaning standards <a href=\"https://reurl.cc/86Ga3o\">https://reurl.cc/86Ga3o</a>) and equipment. If you have any questions, please report them to the dormitory administrator immediately.</p>\r\n\r\n<ol>\r\n	<li>According to Regulations for Student Dormitories, dormitory beds cannot be transferred or adjusted without permission. If beds are occupied when checking in, please do not agree to exchange beds privately. Please inform the dormitory administrator for assistance.</li>\r\n	<li>If you want to apply for the specific dormitory room, please refer to &ldquo;iNCU-&gt;Student Affair (StdAffair) -&gt;Dorm Application and Search -&gt; Vacancies&rdquo; online.</li>\r\n</ol>\r\n\r\n<ol>\r\n	<li>Others.</li>\r\n</ol>\r\n\r\n<ol>\r\n	<li>For the charging standards of each dormitory, please refer to the National Central University Student Dormitory Fee Schedule (applicable for the 2025 academic year).</li>\r\n	<li>The Ministry of Education subsidizes the accommodation fee for students in colleges and universities at NT$5,000 per semester for general students and NT$7,000 per semester for low-income/middle-income students. Please inform your identity when applying.</li>\r\n	<li>The electricity fee for the G14, B13, International Dorm, His-Wang Dorm and NCU Guest House must be paid by oneself.</li>\r\n	<li>There are a few beds in the NCU Guest House. The accommodation will be arranged by the application order. If the beds are full by the time of the application, other dormitory will be arranged for you.</li>\r\n	<li>The His-Wang Dorm is a gender-friendly dormitory, where men and women live in separate buildings and share the public area and the same entrance. NCU Guest House is a gender-friendly dormitory. There is no separate distinction between male and female floors. The common areas are shared, and the entrance is the same.</li>\r\n	<li>Regarding to the dorm network in NCU Guest House, the meeting for charging the dorm network in NCU Guest House on March 13, 2023 by Computer center. In response to the current situation and needs of the dorm network in NCU Guest House, Computer Center has taken the cost into account. They will not provide the dorm network in NCU Guest House in the next academic year. Students who need dorm network could use the solution provided by NCU Guest House (Chunghwa Telecom fixed network).</li>\r\n	<li>Dormitory No. 14 (Female) is scheduled to undergo renovation from July to September of 2026 for a period of one year. During this time, residents will be required to relocate to other dormitories. Further announcements will be made once the project details are finalized.</li>\r\n</ol>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Student Services and Dormitory Division, Office of Student Affairs</p>\r\n',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,33,'2025-12-12 14:18:21',3,0,3),(3228,'交通安全報您知第46期「115年寒假及農曆春節連假期間交通安全宣導」',NULL,1,'2025-12-22 00:00:00','2026-02-10 00:00:00',NULL,NULL,NULL,'<p><strong>各位同學好</strong><strong>:&nbsp;</strong></p>\r\n\r\n<p><strong>因應</strong><strong>115</strong><strong>年寒假及農曆春節連假期間，外出活動，請注意下列交</strong></p>\r\n\r\n<p><strong>安宣導，避免肇生交通意外事故</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>(</strong><strong>一</strong><strong>)</strong><strong>剛考上駕照及剛會駕車上路同學，應避免進入交通擁擠路況</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>、山區及路況不熟地區駕車。</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>(</strong><strong>二</strong><strong>)</strong><strong>盡量多搭乘大眾運輸工具外出或出遊，避免造成交通壅塞。</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>(</strong><strong>三</strong><strong>)</strong><strong>天氣不穩定時，駕車或騎車一定要開大燈或日行燈，確保行</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>車安全；行經人 孔蓋及標線時應特別注意路滑，尤其雨天視</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>線不佳，盡量避免外出，減速慢行，俾減少事故發生。</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>(</strong><strong>四</strong><strong>)</strong><strong>騎乘「機車」等交通工具， 應遵守交通規則， 切勿「無照駕</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>駛</strong>&nbsp; <strong>」、「酒後駕車」及「疲勞駕駛」等危險行為，且須配戴</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp; <strong>「安全帽」，俾防範交通意外事件之發生。</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>(</strong><strong>五</strong><strong>)</strong><strong>連續假期聚餐活動多，易有飲酒助興之情形，考量飲酒對</strong><strong>車</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>輛駕駛人操控影響甚巨，常會伴隨反應遲鈍，速度及判斷</strong><strong>力</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>皆會明顯下降 因此切勿飲酒駕車，以免危害他人及自身安全</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>，如有飲酒需求，請</strong><strong>搭</strong><strong>乘</strong><strong>計程車</strong><strong>、</strong><strong>大眾</strong><strong>交通工具，或指定</strong><strong>代</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>駕服務前往目的地。</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>(</strong><strong>六</strong><strong>)</strong><strong>若想瞭解欲前往地區之行車危險路段，做好防禦駕駛，請</strong><strong>參</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>考生輔組交通安全網頁製作的「校園附近車禍肇事排行及</strong></p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <strong>分析」或「交通風險地圖」相關連結</strong>&nbsp;</p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;<strong>https://military.ncu.edu.tw/traffic.php</strong></p>\r\n',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,29,'2025-12-22 14:41:59',3,0,1),(3229,'針對近日臺北捷運隨機傷人社會案件，請本校各單位及師生加強相關作為',NULL,1,'2025-12-26 00:00:00','2026-02-28 00:00:00',NULL,NULL,NULL,'<p><strong>■針對近日臺北捷運隨機傷人社會案件，請本校各單位及師生加強以下相關作為</strong></p>\r\n\r\n<p><strong>【因應臺北捷運隨機傷人事件，請本校各單位強化校園安全防護機制，落實「預防、應處、輔導」三級防護工作，共維師生安全】：</strong></p>\r\n\r\n<p><strong>一、近期北捷攻擊事件，為確保校園安全及避免模仿效應，請各單位加強下列面向執行：</strong></p>\r\n\r\n<p><strong>&nbsp; </strong><strong>(</strong><strong>一)強化預防機制：</strong></p>\r\n\r\n<p>&nbsp;&nbsp; １、依教育部「校園安全及災害事件通報作業要點、維護校園安全實施要點、校園安全防護注意事項、強化校園防護機制實施計畫」，進行校園安全預防措施，防患未然。</p>\r\n\r\n<p>&nbsp;&nbsp; ２、各單位加強門禁管理與巡查密度：請針對校園(館舍)死角、停車場及開放空間，加強巡查密度及可疑通報。</p>\r\n\r\n<p>&nbsp;&nbsp; ３、校園安全設施檢測：請各單位全面檢視監視器、緊急求助系統(功能是否正常運作)，再與中壢警察分局確認及簽訂「校園安全支援約定書」。</p>\r\n\r\n<p>&nbsp;&nbsp; ４、師長及家長應主動關懷學生日常情緒反應，提早發現問題，提供輔導協助。</p>\r\n\r\n<p><strong>&nbsp; </strong><strong>(</strong><strong>二)落實應處措施：</strong></p>\r\n\r\n<p>&nbsp;&nbsp; １、請全校師生下載-警政署「警政服務報案App」，以備緊急運用。</p>\r\n\r\n<p>&nbsp;&nbsp; ２、校園遇突發暴力事件，應立即啟動「重大緊急校安事件處理流程」，校安中心24小時進行處置及通報。</p>\r\n\r\n<p>&nbsp;&nbsp; ３、師生隨時保持危機應變能力，提高警覺性，增加因應突發危機之成功率。</p>\r\n\r\n<p><strong>二、學生輔導作為：</strong></p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp;臺北捷運發生隨機傷人事件發生後，各院系應留意學生出席及學習情形，倘有擔憂、不安等情緒反應，應傾聽與理解學生感受，協助舒緩焦慮。倘學生有輔導需求，諮商輔導中心應即安排及協助(避免模仿效應)。</p>\r\n\r\n<p><strong>三、強化課程教育：</strong></p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp;為防範類案，應加強法治教育與生命教育，請各系透過課程安排、主題宣導等方式，使學生瞭解法律責任之嚴重性，強化守法觀念，共同營造安全、尊重與關懷的校園環境。</p>\r\n\r\n<p><strong>四、緊急求助管道：</strong></p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp;師生任何時間於校園內遭遇危安狀況，請立即通報下列單位處置：</p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp;校安中心24小時專線：03-2805666</p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp;駐警隊24小時專線：03-4267144</p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp;(★毋須嘗試與歹徒搏鬥，立即通報專人緊急處理)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>國立中央大學 學務處生輔組(校安中心) &nbsp;敬上</p>\r\n\r\n<p>114.12.26</p>\r\n',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,29,'2025-12-26 11:38:44',3,1,3),(3230,'【公告】114學年度第2學期大一週會及院週會',NULL,4,'2026-01-16 00:00:00','2026-06-30 00:00:00','https://cis.ncu.edu.tw/iNCU/messageNotice/activityManagement/activity/1394','https://www.facebook.com/profile.php?id=100071097999985','https://service-learning.ncu.edu.tw/QA/life','<p>114學年度第2學期大一週會及院週會 (週二10:00~12:00)</p>\r\n\r\n<p>報名網址：<a href=\"https://cis.ncu.edu.tw/iNCU/messageNotice/activityManagement/activity/1394\">https://cis.ncu.edu.tw/iNCU/messageNotice/activityManagement/activity/1394</a></p>\r\n\r\n<p>關於大一週會時數問題，詳見服務學習時數Q&amp;A, 詳見&nbsp;<a href=\"https://service-learning.ncu.edu.tw/QA/life\">https://service-learning.ncu.edu.tw/QA/life</a></p>\r\n\r\n<p>FB粉絲專頁：請搜尋【<a href=\"https://www.facebook.com/profile.php?id=100071097999985&amp;locale=zh_TW\">中央大學週會</a>】</p>\r\n\r\n<p>大一週會<br />\r\n3/03校慶講座1(教研大樓大禮堂)，主講人：楊鎮華 資訊工程講座教授<br />\r\n3/17校慶講座2(教研大樓大禮堂)，主講人：孫慶成 光電講座教授<br />\r\n4/07校學士宣導講座(教研大樓大禮堂)，主講人：政大校學士辦公室主任陳宜秀<br />\r\n4/28校慶講座3(教研大樓大禮堂)，主講人：天文所陳婷琬 助理教授<br />\r\n5/26校慶講座4(教研大樓大禮堂)，主講人：生科系許斐婷 副教授<br />\r\n<br />\r\n院週會：<br />\r\n3/10地科院週會(秉文堂)<br />\r\n3/24管院週會(校史館2樓大講堂)<br />\r\n3/24工院週會(秉文堂)<br />\r\n3/31文學院(羅家倫講堂)<br />\r\n5/12理學院週會(校史館2樓大講堂）<br />\r\n5/12生醫理工院週會(太遙中心R3-103視聽室)，王思涵顧問主講<br />\r\n5/19資電院週會(校史館2樓大講堂)<br />\r\n(日期待定)客家學院週會(客家學院國際會議廳)</p>\r\n',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,43,'2026-01-16 10:21:33',3,1,1);
