INSERT INTO `resource_categories` VALUES (1,'life-guidance','{\"en-US\": \"Student Service\", \"zh-TW\": \"生活輔導\"}','{\"en-US\": \"Covers military service affairs, student loans, scholarships, disadvantaged student support, and general student life inquiries.\", \"zh-TW\": \"包含兵役業務、就學貸款、獎助學金、弱勢學生扶助及各項學生生活事務諮詢。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(2,'student-housing','{\"en-US\": \"Student Dormitory Service\", \"zh-TW\": \"學生住宿\"}','{\"en-US\": \"Provides dormitory applications, refunds, facility maintenance requests, safety regulations, and housing management info.\", \"zh-TW\": \"提供宿舍申請、退費處理、宿舍設施修繕報修、宿舍安全規範及生活管理資訊。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(3,'health-services','{\"en-US\": \"Health Center\", \"zh-TW\": \"衛生保健\"}','{\"en-US\": \"Includes campus first aid, medical equipment rental, student group insurance, health checkups, and epidemic prevention.\", \"zh-TW\": \"包含校園急救處理、醫療器材借用、學生團體保險、健康檢查及校園防疫相關服務。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(4,'counseling-services','{\"en-US\": \"Counseling Center\", \"zh-TW\": \"諮商輔導\"}','{\"en-US\": \"Offers individual counseling, group sessions, psychological assessments, career exploration, and life education.\", \"zh-TW\": \"提供個別心理諮商、團體輔導、心理測驗評評估、職涯心理探索及生命教育推廣。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(5,'extracurricular-activities','{\"en-US\": \"Extracurricular Activity Section\", \"zh-TW\": \"課外活動\"}','{\"en-US\": \"Manages student clubs, activity funding, venue bookings for campus events, and coordination of major celebrations.\", \"zh-TW\": \"管理學生社團運作、活動經費補助、校園活動場地借用及各類大型慶典活動協辦。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(6,'career-development','{\"en-US\": \"Career Center\", \"zh-TW\": \"職涯輔導\"}','{\"en-US\": \"Provides internship opportunities, campus recruitment events, career seminars, job matching, and resume/interview coaching.\", \"zh-TW\": \"提供企業實習機會、校園徵才活動、職涯講座、就業媒合與履歷面試技巧指導。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(7,'service-learning','{\"en-US\": \"Service-Learning Division\", \"zh-TW\": \"服務學習\"}','{\"en-US\": \"Handles service-learning course management, volunteer hour certification, social practice projects, and service club links.\", \"zh-TW\": \"負責服務學習課程管理、志工時數認證、社會實踐計畫及服務性社團對接。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL),(8,'miscellaneous','{\"en-US\": \"Others\", \"zh-TW\": \"其他\"}','{\"en-US\": \"Other student affairs resources, administrative announcements, and general service guides not fitting specific categories.\", \"zh-TW\": \"不屬於上述特定類別的其他學務資源、行政公告與綜合性服務指南。\"}',0,1,NULL,'2026-01-25 09:15:26','2026-01-25 09:15:26',NULL);
/*!40000 ALTER TABLE `resource_categories` ENABLE KEYS */;
UNLOCK TABLES;

