CREATE TABLE `resources` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int unsigned NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'link' COMMENT '資源類型',
  `title` json NOT NULL COMMENT '名稱 {"zh-TW": "...", "en-US": "..."}',
